let refreshVersion=0;
function scheduleRefresh(soon=false){
 clearTimeout(pollTimer);
 const editing=Boolean(activeModal)||Boolean(document.hidden)||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);
 const delay=BuiltWatchStatus.pollDelay({signedIn:session.signed_in,demo:state?.demo,view,jobStatus:state?.job?.status,editing});
 if(delay===null)return;
 pollTimer=setTimeout(async()=>{
  if(activeModal||document.hidden||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)){scheduleRefresh();return;}
  try{await refresh();}catch(err){connectionError(err);scheduleRefresh();}
 },soon?12000:delay);
}
