// Every profile save keeps the backend map consistent with the profile it travels with.
function withMap(path,body,method){if(path==='/api/systems'&&body&&!method)return BuiltWatchArchMap.reconcile(body);if(path==='/api/systems/bulk'&&Array.isArray(body?.systems))return {...body,systems:body.systems.map(x=>BuiltWatchArchMap.reconcile(x))};return body;}
async function api(path,body,method){body=withMap(path,body,method);if(state?.demo&&!['/api/session','/api/workspace','/api/connections','/api/admin','/api/public-impact','/api/feedback'].includes(path)&&!path.startsWith('/api/auth/'))return BuiltWatchDemo.request(path,body,method);return BuiltWatchClient.request(apiBase(),token,path,body,method);}
function connectionError(err){
  if(err.status===401){session.signed_in=false;state=structuredClone(demo);render();toast('Please sign in again.');return;}
  if(state&&!state.demo){render();const notice=document.createElement('div');notice.className='notice';notice.setAttribute('role','alert');notice.textContent=err.message;$('#view').prepend(notice);return;}
  $('#view').innerHTML=empty('Your workspace is temporarily unavailable',esc(err.message),'<button class="button primary" data-action="refresh">Try again</button>');
}
async function refresh(){
  const revision=++refreshVersion;
  clearTimeout(pollTimer);
  if(window.BUILTWATCH_OFFLINE){state=BuiltWatchDemo.get();render();return;}
  let impact=globalImpact;
  if(view==='impact'){try{impact=await api('/api/public-impact');}catch{}}
  const previousAdmission=session.admitted;
  let nextSession,nextState;
  try{nextSession=await api('/api/session');nextSession.admitted=previousAdmission;}catch(err){
   if(revision!==refreshVersion)return;
   if(!state)state=BuiltWatchDemo.get();
   if(state.demo)render();
   toast('Live service unavailable. Your last view has been kept. Try Refresh again.');scheduleRefresh();return;
  }
  try{nextState=nextSession.signed_in&&!forceDemo?await api('/api/workspace'):BuiltWatchDemo.get();if(!forceDemo)nextSession.admitted=!nextState.demo;}catch(err){
   if(revision!==refreshVersion)return;
   if(err.code==='pilot_full')nextSession.admitted=false;
   session=nextSession;
   // Do not silently replace a private workspace with sample data on transient errors.
   if(!state||state.demo||!session.signed_in){state=BuiltWatchDemo.get();render();}
   toast(err.message+' Please try Refresh again.');scheduleRefresh();return;
  }
  if(revision!==refreshVersion)return;
  globalImpact=impact;session=nextSession;state=nextState;
  considerReviewAlerts();
  if(!activeModal&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))render();
  scheduleRefresh();
}
