  const existing=intakeTarget?state.systems.find(x=>x.id===intakeTarget):null;intakeSource=existing?.source_agent||'';
  modal(intakeTarget?'Update from your agent':'Import one app from your agent',intakeTarget?'Paste the updated summary from the agent that knows this project.':'Your project agent already knows the details. Copy the request, then paste its answer here.',`<form id="intake-form"><section class="agent-first"><div><span class="eyebrow">STEP 1</span><h3>Ask your project agent</h3><p>It inspects the project context it already has and returns a safe summary.</p><small class="copy-help">Copy it here, paste it into your agent, then come back to this window.</small></div><button type="button" class="button" data-action="copy-builder">Copy request</button></section><div class="field"><label for="app-description">Paste your agent’s summary</label><textarea id="app-description" required minlength="20" maxlength="12000" style="min-height:170px" placeholder="Paste the summary your project agent prepared…"></textarea><small>${state.demo?'The demo prepares the profile locally without a model call.':'BuiltWatch organizes the imported summary into a profile.'} You review it before saving.</small></div><label class="button" for="summary-file">Upload summary file</label><input id="summary-file" type="file" accept=".txt,.md,.json" hidden>${!state.demo?'<p><button type="button" class="text-button" data-action="connections">Connect an agent for future updates →</button></p>':''}<p class="section-note">The imported profile is labeled <strong>Project agent</strong> unless the agent supplies its own name. Do not include source code, passwords, keys, or customer records.</p><p class="error" id="form-error" role="alert"></p><div class="modal-actions"><button class="button primary" type="submit">Review profile →</button><button class="text-button" type="button" data-action="manual">Add manually instead</button></div></form>`);
