function deadlineRows(findings){return findings.map(f=>{const w=BuiltWatchDeadlines.of(f);if(!w||w.passed)return null;const s=state.systems.find(x=>x.id===f.system_id),l=s?BuiltWatchArchMap.landing(s,f):null;return {id:f.id,date:w.date,phrase:w.phrase,summary:`${s?.name||f.system_id}: ${BuiltWatchVisuals.short(f.title,80)}`,detail:[`Source: ${f.source_id}`,l&&!l.whole?`Lands on: ${l.parts.map(c=>c.name).join(', ')}`:'',`Review status: ${f.relevance.replace(/_/g,' ')}`].filter(Boolean).join('\n')};}).filter(Boolean);}
