function exportFinding(id){const f=state.findings.find(x=>x.id===id);let text=`# ${f.title}\n\nSystem: ${systemName(f.system_id)}\nAssessment: ${f.relevance}\nStatus: ${f.adoption_status}\n${state.demo?'\nHISTORICAL REPLAY — saved demonstration, not a live change alert.\n':''}`;for(const [heading,items] of [['Source facts',f.facts],['Reasoning',f.inferences],['App-specific consequence',f.app_impact?[f.app_impact.consequence]:[]],['Review question',f.app_impact?[f.app_impact.review_question]:[]],['System facts',f.system_facts.map(x=>`${x.key}: ${x.value}`)],['Unknowns',f.unknowns],['Review steps',f.review_suggestions]])text+=`\n## ${heading}\n\n`+items.map(x=>'- '+x).join('\n')+'\n';text+='\n## Evidence\n';for(const e of f.evidence)text+=`\n${source(e.source_id)?.name}\n${source(e.source_id)?.url}\n\n> ${e.passage.replaceAll('\n','\n> ')}\n`;text+='\nA review prompt, not a legal or compliance determination.\n';download(`builtwatch-${f.system_id}-handoff.md`,text);toast('Handoff downloaded. Share it with your builder.');}
